Object.entries(adminPortalTranslations).forEach(([language, values]) => {
  if (translations[language]) {
    Object.assign(translations[language], values);
  } else {
    // For languages not in adminPortalTranslations (gu, ta, bn, te, kn), use English keys
    translations[language] = Object.assign({}, translations[language] || {}, adminPortalTranslations.en);
  }
});

// For languages not explicitly in adminPortalTranslations, copy English admin keys
['gu', 'ta', 'bn', 'te', 'kn'].forEach((lang) => {
  if (translations[lang]) {
    Object.assign(translations[lang], adminPortalTranslations.en);
  }
});

export const LanguageProvider = ({ children }) => {
  const [language, setLanguageState] = useState(localStorage.getItem('coopserve_lang') || 'en');

  const setLanguage = (lang) => {
    if (translations[lang]) {
      setLanguageState(lang);
      localStorage.setItem('coopserve_lang', lang);
    }
  };

  const t = (key, defaultText) => {
    return translations[language]?.[key] || (language !== 'en' ? translations.hi?.[key] : null) || translations['en']?.[key] || defaultText || key;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage, t, availableLanguages: [
      { code: 'en', label: 'English',   flag: '🇬🇧' },
      { code: 'hi', label: 'हिन्दी',    flag: '🇮🇳' },
      { code: 'mr', label: 'मराठी',     flag: '🇮🇳' },
      { code: 'gu', label: 'ગુજરાતી',  flag: '🇮🇳' },
      { code: 'ta', label: 'தமிழ்',    flag: '🇮🇳' },
      { code: 'bn', label: 'বাংলা',     flag: '🇮🇳' },
      { code: 'te', label: 'తెలుగు',   flag: '🇮🇳' },
      { code: 'kn', label: 'ಕನ್ನಡ',    flag: '🇮🇳' },
    ] }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = () => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
};
